using System.Diagnostics;
using System.Text.Json;
using Xunit;

namespace Apogeu.Rounds.Tests.Support;

/// <summary>
/// The hub contract v2 of <c>RoundsHub</c> as generated by the SPEC-0006 exporter
/// (<c>dotnet Apogeu.HubContracts.dll --assembly Apogeu.Rounds.Features.dll --output &lt;manifest.json&gt;</c>), i.e. the same
/// JSON Schemas the TypeScript contract of SPEC-0010 is generated from.
/// </summary>
internal sealed class RoundsHubManifest
{
    private readonly JsonElement _hub;

    private RoundsHubManifest(JsonElement hub) => _hub = hub;

    public static async Task<RoundsHubManifest> GenerateAsync(CancellationToken ct)
    {
        var output = Path.Combine(Path.GetTempPath(), "apogeu-rounds-hubs-" + Guid.NewGuid().ToString("N") + ".json");
        var features = Path.Combine(AppContext.BaseDirectory, "Apogeu.Rounds.Features.dll");
        Assert.True(File.Exists(ExporterPath), $"Expected the hub exporter at {ExporterPath}; build the solution first.");

        var start = new ProcessStartInfo("dotnet") { UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true };
        foreach (var argument in (string[])[ExporterPath, "--assembly", features, "--output", output])
        {
            start.ArgumentList.Add(argument);
        }

        using var process = Process.Start(start)!;
        var stdout = process.StandardOutput.ReadToEndAsync(ct);
        var stderr = process.StandardError.ReadToEndAsync(ct);
        await process.WaitForExitAsync(ct).ConfigureAwait(false);
        Assert.True(
            process.ExitCode == 0,
            $"The hub exporter failed ({process.ExitCode}): {await stdout.ConfigureAwait(false)} {await stderr.ConfigureAwait(false)}");

        try
        {
            using var document = JsonDocument.Parse(await File.ReadAllTextAsync(output, ct).ConfigureAwait(false));
            var hub = document.RootElement.GetProperty("hubs").EnumerateArray()
                .SingleOrDefault(h => string.Equals(h.GetProperty("name").GetString(), "RoundsHub", StringComparison.Ordinal));
            Assert.True(hub.ValueKind == JsonValueKind.Object, $"The generated contract has no RoundsHub: {document.RootElement.GetRawText()}");
            return new RoundsHubManifest(hub.Clone());
        }
        finally
        {
            File.Delete(output);
        }
    }

    /// <summary>Schema of the single argument of the client method <paramref name="method"/>.</summary>
    public JsonElement ClientArgument(string method) => Method("client", method).GetProperty("parameters")[0].GetProperty("schema");

    /// <summary>Schema of the result of the server method <paramref name="method"/>.</summary>
    public JsonElement ServerResult(string method) => Method("server", method).GetProperty("returns");

    private static string ExporterPath
    {
        get
        {
            var output = new DirectoryInfo(Path.TrimEndingDirectorySeparator(AppContext.BaseDirectory));
            var configuration = output.Parent?.Name ?? "Debug";
            return Path.Combine(RepositoryRoot(), "tools", "contracts", "HubContracts", "bin", configuration, output.Name, "Apogeu.HubContracts.dll");
        }
    }

    private JsonElement Method(string side, string name)
    {
        var method = _hub.GetProperty(side).EnumerateArray()
            .SingleOrDefault(m => string.Equals(m.GetProperty("name").GetString(), name, StringComparison.Ordinal));
        Assert.True(method.ValueKind == JsonValueKind.Object, $"The generated RoundsHub contract has no {side} method {name}: {_hub.GetRawText()}");
        return method;
    }

    private static string RepositoryRoot()
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
        {
            if (File.Exists(Path.Combine(directory.FullName, "docs", "specs", "sdd-config.yml")))
            {
                return directory.FullName;
            }
        }

        throw new InvalidOperationException($"Repository root not found above {AppContext.BaseDirectory}.");
    }
}
